        opts = "".join(args)
        kinds = []
        if not any(x in ("-l", "--lines", "-w", "--words", "-c", "--bytes", "-m", "--chars") for x in args):
            kinds = [("L", "W", "B")]
        else:
            kinds = [("L" if x in ("-l", "--lines") else "W" if x in ("-w", "--words") else "B" if x in ("-c", "--bytes") else "C") for x in args if x in ("-l", "--lines", "-w", "--words", "-c", "--bytes", "-m", "--chars")]
        if len(kinds) == 1 and isinstance(kinds[0], tuple):
            labels = [f"{n}{k}" for n, k in zip(nums, kinds[0])]
        else:
            labels = nums
        return " ".join(labels) + (" " + name if name else "") + "\n", p.stderr, p.returncode
    # Multiple inputs: compact individual rows and a compact aggregate.
    lines = []
