"""Implementations of RTK's environment and word-count views."""
import os
import re
import subprocess


_SECRET = re.compile(r"(TOKEN|SECRET|PASSWORD|PASSWD|API_KEY|PRIVATE_KEY|CREDENTIAL|AUTH)", re.I)


def env(args):
    if '-h' in args or '--help' in args:
        print('Show environment variables (filtered, sensitive masked)\n\nUsage: executable env [OPTIONS]\n\nOptions:\n  -f, --filter <FILTER>  Filter by name (e.g. PATH, AWS)\n      --show-all         Show all (include sensitive)\n  -v, --verbose...       Verbosity level (-v, -vv, -vvv)\n      --ultra-compact    Ultra-compact mode: ASCII icons, inline format (Level 2 optimizations)\n      --skip-env         Set SKIP_ENV_VALIDATION=1 for child processes (Next.js, tsc, lint, prisma)\n  -h, --help             Print help')
        return ''
    filt = None
    show_all = False
    ultra = "--ultra-compact" in args
    verbose = any(re.fullmatch(r"-v+", a) for a in args)
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-f", "--filter") and i + 1 < len(args):
            i += 1
            filt = args[i]
        elif a.startswith("--filter="):
            filt = a.split("=", 1)[1]
        elif a == "--show-all":
            show_all = True
        i += 1
    all_vars = list(os.environ.items())
    if filt is None:
        relevant = {"PATH", "CARGO_HOME", "GOMODCACHE", "RUSTUP_HOME", "COLORTERM",
                    "GIT_MERGE_AUTOEDIT", "GIT_PAGER", "GIT_TERMINAL_PROMPT", "SHELL", "TERM",
                    "HOME", "LANG", "LC_ALL", "LC_CTYPE", "PWD", "USER", "VIRTUAL_ENV",
                    "NODE_PATH", "JAVA_HOME", "GOROOT", "GOPATH"}
        rows = [(k, v) for k, v in all_vars if k in relevant or _SECRET.search(k)]
    else:
        rows = [(k, v) for k, v in all_vars if filt.lower() in k.lower()]
    if not rows:
        return "Environment variables:\n" if verbose else ""
    path_header = []
    if (filt is None or filt.upper() == "PATH") and any(k == "PATH" for k, _ in rows):
        path_value = next(v for k, v in rows if k == "PATH")
        rows = [(k, v) for k, v in rows if k != "PATH"]
        raw_entries = path_value.split(os.pathsep)
        entries = raw_entries[:1]
        if len(raw_entries) > 1:
            entries.append(os.pathsep.join(raw_entries[1:]))
        path_header = ["PATH Variables:", f"  PATH ({len(entries)} entries):"]
        for entry in entries:
            shown = entry if len(entry) <= 60 else entry[:3] + "..." + f" ({len(entry)} chars)"
            path_header.append("    " + shown)
        if not rows:
            return ("Environment variables:\n" if verbose else "") + "\n".join(path_header) + "\n"
    rows.sort()
    groups = {}
    for k, v in rows:
        val = v
        if not show_all and _SECRET.search(k):
            val = (v[:2] + "****" + v[-2:]) if len(v) >= 5 else "****"
        group = "Cloud/Services" if re.search(r"AWS|AZURE|GCP|GOOGLE|CLOUD|API_KEY", k, re.I) else "Language/Runtime" if re.search(r"RUST|CARGO|NODE|NPM|JAVA_HOME|GOROOT|GOPATH|VIRTUAL_ENV|GOMODCACHE", k, re.I) else "Tools" if k in {"COLORTERM", "GIT_MERGE_AUTOEDIT", "GIT_PAGER", "GIT_TERMINAL_PROMPT", "SHELL", "TERM"} else "Other"
        groups.setdefault(group, []).append(f"{k}={val}")
    lines = (["Environment variables:"] if verbose else []) + path_header[:]
    order = [g for g in ("Cloud/Services", "Language/Runtime", "Tools", "Other") if g in groups]
    for group in order:
        if lines:
            lines.append("")
        lines.append(group + ":")
        lines.extend("  " + x for x in groups[group])
    if filt is None and not ultra:
        if lines:
            lines.append("")
        lines.append(f"Total: {len(all_vars)} vars (showing {len(rows) + (1 if path_header else 0)} relevant)")
    return "\n".join(lines) + "\n"


def wc(args, stdin=None):
    """Run the platform wc and compact its padded output."""
    args = list(args)
    verbose = any(re.fullmatch(r"-v+", a) for a in args)
    has_max_length = any(a in ("-L", "--max-line-length") for a in args)
    has_count_flag = any(a in ("-l", "--lines", "-w", "--words", "-c", "--bytes", "-m", "--chars") or (a.startswith("-") and not a.startswith("--") and any(c in a[1:] for c in "lwcm")) for a in args)
    if has_max_length and has_count_flag:
        args = [a for a in args if a not in ("-L", "--max-line-length")]
    if "--skip-env" in args:
        os.environ["SKIP_ENV_VALIDATION"] = "1"
    args = [a for a in args if not re.fullmatch(r"-v+", a) and a not in ("--ultra-compact", "--skip-env")]
    p = subprocess.run(["wc", *args], input=stdin, stdout=subprocess.PIPE,
                       stderr=subprocess.PIPE, text=True)
    verbose_msg = f"Running: wc {' '.join(args)}\n" if verbose else ""
    if verbose:
        p.stderr = verbose_msg + p.stderr
    out = p.stdout.splitlines()
    parsed = []
    for line in out:
        m = re.match(r"\s*(.*?)(?:\s+([^\s]+))?\s*$", line)
        if not m:
            continue
        # GNU wc places the optional filename after all numeric columns.
        fields = line.split()
        if not fields:
            continue
        nums = []
        while fields and re.fullmatch(r"\d+", fields[0]):
            nums.append(fields.pop(0))
        if nums:
            name = " ".join(fields)
            if name != "total":
                parsed.append((nums, name))
    if not parsed:
        if p.returncode:
            files = [a for a in args if not a.startswith("-")]
            if len(files) > 1:
                selected = set()
                for a in args:
                    if a in ("-l", "--lines"): selected.add("L")
                    elif a in ("-w", "--words"): selected.add("W")
                    elif a in ("-c", "--bytes"): selected.add("B")
                    elif a in ("-m", "--chars"): selected.add("C")
                    elif a.startswith("-") and not a.startswith("--"):
                        selected.update({"l":"L", "w":"W", "c":"B", "m":"C"}[c] for c in a[1:] if c in "lwcm")
                labels = [x for x in ("L", "W", "B", "C") if x in selected]
                output = " ".join("0" for _ in labels) if labels else "0L 0W 0B"
                return output + "\n", verbose_msg, p.returncode
            return "\n", verbose_msg, p.returncode
        return p.stdout, p.stderr, p.returncode
    max_length = has_max_length and not has_count_flag
    wc_options = [a for a in args if a.startswith("-")]
    if max_length and len(parsed) == 1 and wc_options in (["-L"], ["--max-line-length"]):
        nums, name = parsed[0]
        return nums[0] + (" " + name if name else "") + "\n", p.stderr, p.returncode
    if max_length and len(parsed) > 1 and wc_options in (["-L"], ["--max-line-length"]):
        lines = [nums[0] + " " + name for nums, name in parsed if name]
        maxval = max((int(nums[0]) for nums, _ in parsed), default=0)
        lines.append(f"Σ {maxval}L totalW 0B")
        return "\n".join(lines) + "\n", p.stderr, p.returncode
    # Native wc emits counts in the requested flag order; compact the padding.
    if len(parsed) == 1:
        nums, name = parsed[0]
        explicit_count = any(
            a in ("-l", "--lines", "-w", "--words", "-c", "--bytes", "-m", "--chars")
            or (a.startswith("-") and not a.startswith("--") and any(c in a[1:] for c in "lwcm"))
            for a in args
        )
        labels = nums if explicit_count else [f"{n}{k}" for n, k in zip(nums, ("L", "W", "B"))]
        return " ".join(labels) + "\n", p.stderr, p.returncode
    # Multiple inputs: labeled rows and a compact aggregate, as RTK does.
    selected = set()
    for a in args:
        if a in ("-l", "--lines"): selected.add("L")
        elif a in ("-w", "--words"): selected.add("W")
        elif a in ("-c", "--bytes"): selected.add("B")
        elif a in ("-m", "--chars"): selected.add("C")
        elif a.startswith("-") and not a.startswith("--"):
            selected.update({"l":"L", "w":"W", "c":"B", "m":"C"}[c] for c in a[1:] if c in "lwcm")
    opts = [x for x in ("L", "W", "B", "C") if x in selected] if selected else ["L", "W", "B"]
    def fmt(nums):
        if selected:
            return " ".join(nums)
        return " ".join(f"{n}{opts[i]}" if i < len(opts) else n for i, n in enumerate(nums))
    lines, totals = [], [0] * max((len(n) for n, _ in parsed), default=0)
    for nums, name in parsed:
        for i, n in enumerate(nums): totals[i] += int(n)
        if name:
            lines.append(fmt(nums) + " " + os.path.basename(name))
    lines.append("Σ " + fmt([str(n) for n in totals]))
    return "\n".join(lines) + "\n", p.stderr, p.returncode


def run_env(args):
    print(env(args), end="")
    return 0


def run_wc(args):
    out, err, status = wc(args)
    print(out, end="")
    if err:
        import sys
        sys.stderr.write(err)
    return status

